from collections import OrderedDict


class BoundedTTLCache:
    def __init__(self, maxsize, ttl):
        self.maxsize = maxsize
        self.ttl = ttl
        self._cache = OrderedDict()  # key -> (value, stored_time)
        self._access_order = OrderedDict()  # key -> None, tracks LRU order

    def _is_expired(self, stored_time, now):
        return now > stored_time + self.ttl

    def _evict_if_needed(self):
        # Remove expired entries first
        expired_keys = []
        for key in list(self._access_order.keys()):
            if key in self._cache:
                value, stored_time = self._cache[key]
                if self._is_expired(stored_time, 0):  # We can't check expiration without 'now', so defer this
                    pass
        # We'll handle eviction in put/get with the current time

    def put(self, key, value, now):
        # First, clean up any expired entries to free space
        self._cleanup_expired(now)

        if key in self._cache:
            # Update existing key
            self._cache[key] = (value, now)
            # Move to most recently used
            self._access_order.move_to_end(key)
        else:
            if len(self._cache) >= self.maxsize:
                # Evict the least recently used key
                self._evict_lru()
            self._cache[key] = (value, now)
            self._access_order[key] = None

    def _evict_lru(self):
        while self._access_order:
            lru_key, _ = self._access_order.popitem(last=False)
            # Check if the key is actually expired or just stale in access_order
            if lru_key in self._cache:
                del self._cache[lru_key]
            break

    def get(self, key, now):
        # Clean up expired entries
        self._cleanup_expired(now)

        if key not in self._cache:
            return None

        value, stored_time = self._cache[key]
        if self._is_expired(stored_time, now):
            # Remove the expired entry
            del self._cache[key]
            self._access_order.pop(key, None)
            return None

        # Successful get: move to most recently used
        self._access_order.move_to_end(key)
        return value

    def _cleanup_expired(self, now):
        # Remove all expired entries
        expired_keys = []
        for key in list(self._access_order.keys()):
            if key in self._cache:
                value, stored_time = self._cache[key]
                if self._is_expired(stored_time, now):
                    expired_keys.append(key)

        for key in expired_keys:
            del self._cache[key]
            self._access_order.pop(key, None)
