"""Tiny inventory bookkeeping."""

class Inventory:
    def __init__(self):
        self._items = {}

    def add(self, name, qty, unit_price):
        if qty <= 0:
            raise ValueError("qty must be positive")
        entry = self._items.setdefault(name, {"qty": 0, "unit_price": unit_price})
        entry["qty"] += qty
        entry["unit_price"] = unit_price

    def quantity(self, name):
        return self._items.get(name, {}).get("qty", 0)

    def total_value(self):
        return sum(entry["qty"] * entry["unit_price"] for entry in self._items.values())

    def remove(self, name, qty):
        if qty <= 0:
            raise ValueError("qty must be positive")
        entry = self._items.get(name)
        if entry is None:
            raise ValueError(f"unknown item: {name}")
        if entry["qty"] < qty:
            raise ValueError(f"insufficient stock for {name}")
        entry["qty"] -= qty

    def low_stock(self, threshold):
        return sorted(name for name, entry in self._items.items() if entry["qty"] < threshold)
